{"source":"#include<stdio.h>
int main(int argc, char *argv[])
{
    int n,m,count=0,i;
    scanf("%d %d",&n,&m);
    int a[2*m*n];
    for(i=0;i<2*m*n;i++)
    {
        scanf("%d",&a[i]);  
    }
    for(i=0;i<2*m*n;i+=2)
    {
        if((a[i]+a[i+1])>=1)
        {
            count++;
        }
    }
    printf("%d\n",count);
    return 0;
}"}
